async function morePage(){const sections=[['care','每日照護','餐點、飲水、排泄與活動'],['items','入住物品',ITEM_CATEGORIES.slice(0,4).join('、')+'…'],['events','異常紀錄',ABNORMAL_CATEGORIES.slice(0,5).join('、')+'…'],['medications','用藥管理','確認藥單、排程與實際執行'],['reports','飼主日報','依實際紀錄產生、審核與傳送'],['handover','保母交接','未完成事項與重要確認'],['profiles','飼主與貓咪資料','永久資料與住宿快照分離'],['history','歷史紀錄','搜尋照護、物品與通知'],['revenue','營收管理','付款與月營收摘要'],['settings','系統設定','人員、權限與資料移轉']];main.innerHTML=`<div class="page-head"><div><p>${esc(ROLE_LABELS[state.membership?.role]||'預覽人員')}</p><h2>功能總覽</h2></div></div><section class="grid rooms">${sections.map(([key,title,desc])=>`<button class="card stat" data-section="${key}"><strong style="font-size:1rem">${title}</strong><small>${desc}</small></button>`).join('')}</section><section class="card" style="margin-top:14px"><h3>帳號與裝置</h3><p class="muted">${state.cloud?esc(state.session?.user?.email):'尚未連接 Supabase'}</p><div class="actions"><button class="btn secondary" id="legacy">檢查舊版資料</button>${state.cloud?'<button class="btn danger" id="logout">登出</button>':''}</div></section>`;document.querySelector('#legacy').onclick=legacyDialog;if(state.cloud)document.querySelector('#logout').onclick=()=>signOut().then(()=>location.reload());document.querySelectorAll('[data-section]').forEach(button=>button.onclick=()=>sectionInfo(button.dataset.section))}
function sectionInfo(key){if(['care','items','events','medications','reports','handover','profiles','settings'].includes(key))return navigate(key);const copy={history:['歷史紀錄','資料庫提供日期與旅館隔離索引，可依貓咪、飼主、房間或預約查詢。'],revenue:['營收管理','僅業主可看完整付款資料；計價結果永久保存為價格快照。']}[key];const dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-body"><h2>${copy[0]}</h2><p>${copy[1]}</p><p class="muted">資料模型、權限政策與可執行遷移已建立；部分專用操作畫面列於 TASKS.md 後續里程碑。</p><button class="btn" id="ok">知道了</button></div>`;document.body.append(dialog);dialog.querySelector('#ok').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal()}
